use crate::{ivp_managed_contacts::{Managed,Settings},ivp_unit_registry::Registry,
    ivp_create::{Endpoint,Feature},ivp_contact_notifications::Kind};
use serde_json::{Value,json};
use bevy::prelude::Vec3;
fn endpoint(v:&Value)->Endpoint{let f=&v["feature"];Endpoint{object:v["object"].as_u64().unwrap(),feature:Feature{kind:f["kind"].as_i64().unwrap() as i16,edge:f["edge"].as_u64().unwrap(),opposite:f["opposite"].as_u64().unwrap(),triangle:f["triangle"].as_u64().unwrap(),ledge:f["ledge"].as_u64().unwrap(),vertex:f["vertex"].as_u64().unwrap() as u16,vertices:std::array::from_fn(|i|Vec3::from_array(std::array::from_fn(|j|f["vertices"][i][j].as_f64().unwrap() as f32)))}}}

fn split_replay(c:&Value,check:bool)->Vec<Value>{let mut r=Registry::new(4);let fixed=(0..4).map(|i|{r.register_core(i,i==0).unwrap();(i,i==0)}).collect();let mut w=Managed::new(r,fixed,(0..4).map(|i|(i as u64+1,i)).collect(),Settings{distance:c["settings"]["distance"].as_f64().unwrap() as f32,area_epsilon:c["settings"]["area_epsilon"].as_f64().unwrap()}).unwrap();for l in c["listeners"].as_array().unwrap(){w.subscribe(l["id"].as_u64().unwrap() as usize,l["flags"].as_u64().unwrap() as u32).unwrap();}let mut history=vec![];let mut all=vec![];
for(i,row)in c["states"].as_array().unwrap().iter().enumerate(){let op=row.get("output").unwrap_or(row);match op["action"].as_str().unwrap(){
 "initial"=>{},"admit"=>{let input=&row["input"];let h=input["hint"].as_i64().unwrap();w.resolve(input["flags"].as_u64().unwrap() as u32,input["time"].as_f64().unwrap(),std::array::from_fn(|s|endpoint(&input["endpoints"][s])),(h>=0).then_some(h as usize)).unwrap();},
 "clock"=>{let system=op["system"].as_u64().unwrap() as usize;let key=op["contact"].as_u64().unwrap() as usize;let cores=[key/4,key%4];let (index,p)=w.owner().system_pairs(system).unwrap().iter().enumerate().find(|(_,p)|cores.iter().all(|c|p.cores.contains(c))).unwrap();let actual=p.cores;w.set_pair_clock(system,index,actual,crate::ivp_contact_pipeline::FrictionGroup{timer:op["other"].as_i64().unwrap() as i32,energy:0.125*((key+1) as f32)}).unwrap();},
 "repair"=>{let created=w.repair_system(op["system"].as_u64().unwrap() as usize).unwrap();if check{assert_eq!(created.len(),op["other"].as_u64().unwrap() as usize);}},
 "remove"=>w.remove(op["contact"].as_u64().unwrap()).unwrap(),"destroy"=>w.destroy_empty(op["system"].as_u64().unwrap() as usize).unwrap(),_=>panic!("unknown split operation")}
for d in w.take_notifications(){history.push(json!([d.listener,match d.event.kind{Kind::Created=>0,Kind::Deleted=>1,Kind::PairAdded=>2,Kind::PairRemoved=>3},d.event.contact.unwrap_or(0),d.event.cores[0],d.event.cores[1]]));}let mut state=w.snapshot();state["notifications"]=json!(history);if check{for k in ["systems","core_links","contact_bindings","controller_keys","object_links","unit_members","notifications"]{assert_eq!(state[k],op[k],"world{} row{i} {} {k}",c["scenario"],op["action"]);}}all.push(state);
}all}
pub(crate) fn verify(){let data:Value=serde_json::from_str(include_str!("../tools/fixtures/native-ivp-contact-system-split.json")).unwrap();let mut total=0;for c in data["cases"].as_array().unwrap(){let a=split_replay(c,true);total+=a.len();let mut bad=c.clone();for row in bad["states"].as_array_mut().unwrap(){let op=if row.get("output").is_some(){&mut row["output"]}else{row};for k in ["systems","core_links","contact_bindings","controller_keys","object_links","unit_members","notifications"]{op[k]=Value::Null;}}assert_eq!(a,split_replay(&bad,false));}assert_eq!(total,216);println!("native contact-system splitting:8 worlds /216 checkpoints /16 allocations; pair clocks, all link/list/controller orders and notifications match");}
#[test]fn native_contact_system_split_transfers_and_clock_retention_match(){verify();}
